    wsf: { t: 'Water-Scrum-Fall', segs: [['rq', 'ТЗ и бюджет', 4], ['dv', 'Сп.', 2], ['dv', 'Сп.', 2], ['dv', 'Сп.', 2], ['dv', 'Сп.', 2], ['ts', 'Тесты', 3], ['rl', 'Вып.', 2]], users: [0, 0, 0, 0, 0, 0, 1], note: ['warn', 'Снаружи каскад, внутри спринты. Команда работает короткими циклами, но требования утверждены заранее, а пользователи впервые видят продукт на большом выпуске раз в полгода.'] },
