    h += '</div><div class="agl-legend" style="margin-top:8px"><span><i style="background:var(--violet);transform:rotate(45deg);width:9px;height:9px"></i>показ Нине</span><span><i style="background:var(--ok);transform:rotate(45deg);width:9px;height:9px"></i>пробуют кассиры</span><span><i style="background:var(--bad);width:3px"></i>неприятность всплыла</span><span><i style="background:repeating-linear-gradient(45deg,var(--bad) 0 4px,var(--bad-soft) 4px 8px)"></i>переделка</span></div>';
